package com.minecolonies.core.colony.workorders;

import com.google.common.collect.BiMap;
import com.google.common.collect.HashBiMap;
import com.ldtteam.structurize.blockentities.interfaces.IBlueprintDataProviderBE;
import com.ldtteam.structurize.blueprints.v1.Blueprint;
import com.ldtteam.structurize.storage.StructurePacks;
import com.minecolonies.api.colony.ICitizenData;
import com.minecolonies.api.colony.IColony;
import com.minecolonies.api.colony.buildings.IBuilding;
import com.minecolonies.api.colony.workorders.*;
import com.minecolonies.api.util.*;
import com.minecolonies.api.util.constant.Constants;
import com.minecolonies.api.util.constant.NbtTagConstants;
import com.minecolonies.core.colony.buildings.workerbuildings.BuildingBuilder;
import com.minecolonies.core.colony.workorders.view.*;
import com.minecolonies.core.entity.ai.workers.util.BuildingProgressStage;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.network.chat.Component;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.phys.AABB;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

import java.lang.reflect.Constructor;
import java.lang.reflect.InvocationTargetException;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.CompletableFuture;
import java.util.function.Consumer;

import static com.ldtteam.structurize.blockentities.interfaces.IBlueprintDataProviderBE.TAG_BLUEPRINTDATA;
import static com.ldtteam.structurize.blockentities.interfaces.IBlueprintDataProviderBE.TAG_SCHEMATIC_NAME;
import static com.minecolonies.api.util.constant.NbtTagConstants.TAG_STAGE;
import static com.minecolonies.api.util.constant.Suppression.UNUSED_METHOD_PARAMETERS_SHOULD_BE_REMOVED;

/**
 * General information between WorkOrders.
 */
public abstract class AbstractWorkOrder implements IBuilderWorkOrder
{
    /**
     * NBT for storage.
     */
    private static final String TAG_TYPE                = "type";
    private static final String TAG_ID                  = "id";
    private static final String TAG_TH_PRIORITY         = "priority";
    private static final String TAG_CLAIMED_BY          = "claimedBy";
    private static final String TAG_CLAIMED_BY_BUILDING = "claimedByBuilding";
    private static final String TAG_STRUCTURE_PACK      = "structurePack";
    private static final String TAG_STRUCTURE_PATH      = "structurePath";
    private static final String TAG_TRANSLATION_KEY     = "translationKey";
    private static final String TAG_WO_TYPE             = "workOrderType";
    private static final String TAG_LOCATION            = "location";
    private static final String TAG_ROTATION            = "rotation";
    private static final String TAG_IS_MIRRORED         = "isMirrored";
    private static final String TAG_CURRENT_LEVEL       = "currentLevel";
    private static final String TAG_TARGET_LEVEL        = "targetLevel";
    private static final String TAG_AMOUNT_OF_RESOURCES = "amountOfResources";
    private static final String TAG_ITERATOR            = "iterator";
    private static final String TAG_IS_CLEARED          = "cleared";
    private static final String TAG_IS_REQUESTED        = "requested";
    private static final String TAG_BB = "bb";

    /**
     * Bimap of workOrder from string to class.
     */
    @NotNull
    private static final BiMap<String, Tuple<Class<? extends IWorkOrder>, Class<? extends IWorkOrderView>>> nameToClassBiMap = HashBiMap.create();
    /*
     * WorkOrder registry.
     */
    static
    {
        addMapping("building", WorkOrderBuilding.class, WorkOrderBuildingView.class);
        addMapping("decoration", WorkOrderDecoration.class, WorkOrderDecorationView.class);
        addMapping("plantation_field", WorkOrderPlantationField.class, WorkOrderPlantationFieldView.class);
        addMapping("miner", WorkOrderMiner.class, WorkOrderMinerView.class);
    }

    /**
     * Translation key.
     */
    private String translationKey;

    /**
     * The ID of the work order.
     */
    private int id;

    /**
     * The priority of the work order.
     */
    private int priority;

    /**
     * Which building has claimed this work order.
     */
    private BlockPos claimedBy = BlockPos.ZERO;

    /**
     * The structurize schematic name.
     */
    protected String packName;

    /**
     * The work order name.
     */
    private String path;

    /**
     * The work order type.
     */
    private WorkOrderType workOrderType;

    /**
     * The location of this work order its structure.
     */
    private BlockPos location;

    /**
     * The rotation of this work order its structure.
     */
    private int rotation;

    /**
     * Whether the work order its structure is mirrored or not.
     */
    private boolean isMirrored;

    /**
     * The current level of the work order its structure.
     */
    private int currentLevel;

    /**
     * The target level of the work order its structure.
     */
    private int targetLevel;

    /**
     * The amount of resources the work order its structure still requires.
     */
    private int amountOfResources;

    /**
     * The building stage this workorder is in
     */
    private BuildingProgressStage stage = null;

    /**
     * The iterator type (building method) of this work order.
     */
    private String iteratorType;

    /**
     * Whether the work order area is cleared.
     */
    private boolean cleared;

    /**
     * Whether the resources for the work order have been requested.
     */
    private boolean requested;

    /**
     * Internal flag to see if anything has been changed.
     */
    protected boolean changed;

    /**
     * The workorder area
     */
    protected AABB box = Constants.EMPTY_AABB;

    /**
     * The blueprint of this workorders schematic
     */
    protected Blueprint blueprint = null;

    /**
     * The loading future of the blueprint
     */
    protected CompletableFuture<Blueprint> future = null;

    /**
     * Colony this workorder is in
     */
    protected IColony colony = null;

    /**
     * Add a given Work Order mapping.
     *
     * @param name       name of work order
     * @param orderClass class of work order
     */
    private static void addMapping(
      final String name,
      @NotNull final Class<? extends IWorkOrder> orderClass,
      @NotNull final Class<? extends IWorkOrderView> viewClass)
    {
        if (nameToClassBiMap.containsKey(name))
        {
            throw new IllegalArgumentException("Duplicate type '" + name + "' when adding Work Order class mapping");
        }

        try
        {
            if (orderClass.getDeclaredConstructor() != null)
            {
                nameToClassBiMap.put(name, new Tuple<>(orderClass, viewClass));
                nameToClassBiMap.inverse().put(new Tuple<>(orderClass, viewClass), name);
            }
        }
        catch (final NoSuchMethodException exception)
        {
            throw new IllegalArgumentException("Missing constructor for type '" + name + "' when adding Work Order class mapping", exception);
        }
    }

    /**
     * Create a Work Order from a saved CompoundTag.
     *
     * @param compound the compound that contains the data for the Work Order
     * @param manager  the work manager.
     * @return {@link IWorkOrder} from the NBT
     */
    public static IServerWorkOrder createFromNBT(@NotNull final CompoundTag compound, final WorkManager manager)
    {
        @Nullable IServerWorkOrder order = null;
        @Nullable Class<? extends IWorkOrder> oclass = null;

        try
        {
            // TODO: In 1.19 remove this check as this is purely for backwards compatibility with old class mappings
            String type = compound.getString(TAG_TYPE);
            if (type.equals("removal"))
            {
                oclass = WorkOrderBuilding.class;
            }
            else
            {
                oclass = nameToClassBiMap.get(type).getA();
            }

            if (oclass != null)
            {
                final Constructor<?> constructor = oclass.getDeclaredConstructor();
                order = (IServerWorkOrder) constructor.newInstance();
            }
        }
        catch (NoSuchMethodException | InstantiationException | InvocationTargetException | IllegalAccessException e)
        {
            Log.getLogger().trace(e);
        }

        if (order == null)
        {
            Log.getLogger().warn(String.format("Unknown WorkOrder type '%s' or missing constructor of proper format.", compound.getString(TAG_TYPE)));
            return null;
        }

        order.setColony(manager.getColony());

        try
        {
            order.read(compound, manager);
        }
        catch (final RuntimeException ex)
        {
            Log.getLogger().error(String.format("A WorkOrder %s(%s) has thrown an exception during loading, its state cannot be restored. Report this to the mod author",
                compound.getString(TAG_TYPE), oclass.getName()), ex);
            return null;
        }

        return order;
    }

    /**
     * Create a WorkOrder View from a buffer.
     *
     * @param buf The network data
     * @return View object of the workOrder
     */
    @Nullable
    public static IWorkOrderView createWorkOrderView(final FriendlyByteBuf buf)
    {
        @Nullable AbstractWorkOrderView orderView = null;
        String mappingName = buf.readUtf(32767);

        try
        {
            @Nullable Class<? extends IWorkOrderView> oclass = nameToClassBiMap.get(mappingName).getB();

            if (oclass != null)
            {
                final Constructor<?> constructor = oclass.getDeclaredConstructor();
                orderView = (AbstractWorkOrderView) constructor.newInstance();
            }
        }
        catch (InvocationTargetException | NoSuchMethodException | InstantiationException | IllegalAccessException e)
        {
            Log.getLogger().trace(e);
        }

        if (orderView == null)
        {
            Log.getLogger().warn(String.format("Unknown WorkOrder type '%s' or missing constructor of proper format.", mappingName));
            return null;
        }
        try
        {
            orderView.deserialize(buf);
        }
        catch (final RuntimeException ex)
        {
            Log.getLogger().error(String.format("A WorkOrder.View for #%d has thrown an exception during loading, its state cannot be restored. Report this to the mod author",
                orderView.getID()), ex);
            return null;
        }

        return orderView;
    }

    /**
     * Default constructor; we also start with a new id and replace it during loading; this greatly simplifies creating subclasses.
     */
    public AbstractWorkOrder()
    {
        this.iteratorType = "";
        this.changed = false;
    }

    protected AbstractWorkOrder(
        String packName,
        String path,
        String translationKey,
        WorkOrderType workOrderType,
        BlockPos location,
        int rotation,
        boolean isMirrored,
        int currentLevel,
        int targetLevel)
    {
        this();
        this.packName = packName;
        this.path = path;
        this.translationKey = translationKey;
        this.workOrderType = workOrderType;
        this.location = location;
        this.rotation = rotation;
        this.isMirrored = isMirrored;
        this.currentLevel = currentLevel;
        this.targetLevel = targetLevel;
    }

    @Override
    public final int getID()
    {
        return id;
    }

    @Override
    public final void setID(int id)
    {
        this.id = id;
    }

    @Override
    public final int getPriority()
    {
        return priority;
    }

    @Override
    public final void setPriority(int priority)
    {
        if (this.priority == priority)
        {
            return;
        }

        this.priority = priority;
        changed = true;
    }

    @Override
    public final BlockPos getClaimedBy()
    {
        return claimedBy;
    }

    @Override
    public final void setClaimedBy(BlockPos claimedBy)
    {
        if (isClaimed() && !this.claimedBy.equals(claimedBy) && claimedBy != null)
        {
            Log.getLogger().warn("Claiming an already claimed workorder! new claim:" + claimedBy + " old claim:" + this.claimedBy, new Exception());
        }

        changed = true;
        this.claimedBy = claimedBy;
        if (claimedBy == null)
        {
            this.claimedBy = BlockPos.ZERO;
        }
    }

    @Override
    public final boolean isClaimed()
    {
        return !BlockPos.ZERO.equals(claimedBy);
    }

    @Override
    public final String getStructurePath()
    {
        return path;
    }

    @Override
    public String getStructurePack()
    {
        return packName;
    }

    @Override
    public void loadBlueprint(final Level world, final Consumer<Blueprint> afterLoad)
    {
        if (blueprint != null)
        {
            afterLoad.accept(blueprint);
        }
        else if (future == null || future.isDone())
        {
            future = ColonyUtils.queueBlueprintLoad(world, getStructurePack(), getStructurePath(), blueprint ->
                {
                    setBlueprint(blueprint, world);
                    afterLoad.accept(blueprint);
                },
                e -> afterLoad.accept(null));
        }
        else
        {
            afterLoad.accept(null);
        }
    }

    @Override
    public final String getTranslationKey()
    {
        return translationKey;
    }

    @Override
    public final WorkOrderType getWorkOrderType()
    {
        return workOrderType;
    }

    @Override
    public final BlockPos getLocation()
    {
        return location;
    }

    @Override
    public final int getRotation()
    {
        return rotation;
    }

    @Override
    public final boolean isMirrored()
    {
        return isMirrored;
    }

    @Override
    public final int getCurrentLevel()
    {
        return currentLevel;
    }

    @Override
    public final int getTargetLevel()
    {
        return targetLevel;
    }

    @Override
    public final int getAmountOfResources()
    {
        return amountOfResources;
    }

    @Override
    public final void setAmountOfResources(int newQuantity)
    {
        changed = true;
        this.amountOfResources = newQuantity;
    }

    @Override
    public final String getIteratorType()
    {
        return iteratorType;
    }

    @Override
    public final void setIteratorType(String iteratorType)
    {
        changed = true;
        this.iteratorType = iteratorType;
    }

    @Override
    public final boolean isCleared()
    {
        return cleared;
    }

    @Override
    public final void setCleared(boolean cleared)
    {
        changed = true;
        this.cleared = cleared;
    }

    @Override
    public final boolean isRequested()
    {
        return requested;
    }

    @Override
    public final void setRequested(final boolean requested)
    {
        changed = true;
        this.requested = requested;
    }

    @Override
    public final boolean isDirty()
    {
        return changed;
    }

    @Override
    public final void resetChange()
    {
        this.changed = false;
    }

    /**
     * Get the name of the work order, provides the custom name or the work order name when no custom name is given
     *
     * @return the display name for the work order
     */
    @Override
    public Component getDisplayName()
    {
        return Component.translatable(getTranslationKey());
    }

    @Override
    public void setBlueprint(final Blueprint blueprint, final Level world)
    {
        if (blueprint != null && blueprint != this.blueprint)
        {
            this.blueprint = blueprint;
            changed = true;
            final net.minecraft.util.Tuple<BlockPos, BlockPos> corners
                = ColonyUtils.calculateCorners(location,
                world,
                blueprint,
                getRotation(),
                isMirrored());

            box = new AABB(corners.getA(), corners.getB());
        }
    }

    @Override
    public Blueprint getBlueprint()
    {
        return blueprint;
    }

    @Override
    public void clearBlueprint()
    {
        blueprint = null;
        future = null;
    }

    @Override
    public AABB getBoundingBox()
    {
        if (box == Constants.EMPTY_AABB && colony != null && colony.getWorld() != null)
        {
            loadBlueprint(colony.getWorld(), b -> clearBlueprint());
        }

        return box;
    }

    @Override
    public IColony getColony()
    {
        return colony;
    }

    @Override
    public void setColony(final IColony colony)
    {
        this.colony = colony;
    }

    /**
     * Whether the work order can be built or not.
     *
     * @param citizen the citizen attempting to perform the work order
     * @return true if it can be built
     */
    public abstract boolean canBuild(final IBuilding citizen);

    /**
     * Is this WorkOrder still valid?  If not, it will be deleted.
     * <p>
     * Suppressing Sonar Rule squid:S1172 This rule does " Unused method parameters should be removed" But in this case extending class may need to use the colony parameter
     *
     * @param colony The colony that owns the Work Order
     * @return True if the WorkOrder is still valid, or False if it should be deleted
     */
    @Override
    @SuppressWarnings(UNUSED_METHOD_PARAMETERS_SHOULD_BE_REMOVED)
    public boolean isValid(final IColony colony)
    {
        return true;
    }

    /**
     * Read the WorkOrder data from the CompoundTag.
     *
     * @param compound NBT Tag compound
     * @param manager  the workManager calling this method.
     */
    @Override
    public void read(@NotNull final CompoundTag compound, final IWorkManager manager)
    {
        id = compound.getInt(TAG_ID);
        if (compound.contains(TAG_TH_PRIORITY))
        {
            priority = compound.getInt(TAG_TH_PRIORITY);
        }

        if (compound.contains(TAG_CLAIMED_BY))
        {
            final int citizenId = compound.getInt(TAG_CLAIMED_BY);
            if (manager.getColony() != null)
            {
                final ICitizenData data = manager.getColony().getCitizenManager().getCivilian(citizenId);
                if (data != null && data.getWorkBuilding() != null)
                {
                    claimedBy = data.getWorkBuilding().getPosition();
                }
            }
        }
        else if (compound.contains(TAG_CLAIMED_BY_BUILDING))
        {
            claimedBy = BlockPosUtil.read(compound, TAG_CLAIMED_BY_BUILDING);
        }
        packName = compound.getString(TAG_STRUCTURE_PACK);
        path = compound.getString(TAG_STRUCTURE_PATH);
        translationKey = compound.getString(TAG_TRANSLATION_KEY);
        workOrderType = WorkOrderType.values()[compound.getInt(TAG_WO_TYPE)];
        location = BlockPosUtil.read(compound, TAG_LOCATION);
        rotation = compound.getInt(TAG_ROTATION);
        isMirrored = compound.getBoolean(TAG_IS_MIRRORED);
        currentLevel = compound.getInt(TAG_CURRENT_LEVEL);
        targetLevel = compound.getInt(TAG_TARGET_LEVEL);
        amountOfResources = compound.getInt(TAG_AMOUNT_OF_RESOURCES);
        iteratorType = compound.getString(TAG_ITERATOR);
        cleared = compound.getBoolean(TAG_IS_CLEARED);
        requested = compound.getBoolean(TAG_IS_REQUESTED);

        if (compound.contains(TAG_STAGE))
        {
            stage = BuildingProgressStage.values()[compound.getInt(TAG_STAGE)];
        }

        if (compound.contains(TAG_BB))
        {
            CompoundTag tag = (CompoundTag) compound.get(TAG_BB);
            box = new AABB(tag.getInt("minx"), tag.getInt("miny"), tag.getInt("minz"), tag.getInt("maxx"), tag.getInt("maxy"), tag.getInt("maxz"));
        }
    }

    /**
     * Save the Work Order to an CompoundTag.
     *
     * @param compound NBT tag compount
     */
    @Override
    public void write(@NotNull final CompoundTag compound)
    {
        compound.putInt(TAG_TH_PRIORITY, priority);
        compound.putString(TAG_TYPE, getMappingName());
        compound.putInt(TAG_ID, id);
        BlockPosUtil.write(compound, TAG_CLAIMED_BY_BUILDING, claimedBy);
        compound.putString(TAG_STRUCTURE_PACK, packName);
        compound.putString(TAG_STRUCTURE_PATH, path);
        compound.putString(TAG_TRANSLATION_KEY, translationKey);
        compound.putInt(TAG_WO_TYPE, workOrderType.ordinal());
        BlockPosUtil.write(compound, TAG_LOCATION, location);
        compound.putInt(TAG_ROTATION, rotation);
        compound.putBoolean(TAG_IS_MIRRORED, isMirrored);
        compound.putInt(TAG_CURRENT_LEVEL, currentLevel);
        compound.putInt(TAG_TARGET_LEVEL, targetLevel);
        compound.putInt(TAG_AMOUNT_OF_RESOURCES, amountOfResources);
        compound.putString(TAG_ITERATOR, iteratorType);
        compound.putBoolean(TAG_IS_CLEARED, cleared);
        compound.putBoolean(TAG_IS_REQUESTED, requested);
        compound.putInt(TAG_STAGE, stage == null ? 0 : stage.ordinal());

        if (box != Constants.EMPTY_AABB)
        {
            CompoundTag tag = new CompoundTag();
            tag.putInt("minx", (int) box.minX);
            tag.putInt("miny", (int) box.minY);
            tag.putInt("minz", (int) box.minZ);
            tag.putInt("maxx", (int) box.maxX);
            tag.putInt("maxy", (int) box.maxY);
            tag.putInt("maxz", (int) box.maxZ);
            compound.put(TAG_BB, tag);
        }
    }

    /**
     * Writes the workOrders data to a byte buf for transition.
     *
     * @param buf Buffer to write to
     */
    @Override
    public void serializeViewNetworkData(@NotNull final FriendlyByteBuf buf)
    {
        buf.writeUtf(getMappingName());
        buf.writeInt(id);
        buf.writeInt(priority);
        buf.writeBlockPos(claimedBy);
        buf.writeUtf(packName);
        buf.writeUtf(path);
        buf.writeUtf(translationKey);
        buf.writeInt(workOrderType.ordinal());
        buf.writeBlockPos(location);
        buf.writeInt(rotation);
        buf.writeBoolean(isMirrored);
        buf.writeInt(currentLevel);
        buf.writeInt(targetLevel);
        buf.writeInt(stage == null ? 0 : stage.ordinal());
        buf.writeDouble(getBoundingBox().minX);
        buf.writeDouble(getBoundingBox().minY);
        buf.writeDouble(getBoundingBox().minZ);
        buf.writeDouble(getBoundingBox().maxX);
        buf.writeDouble(getBoundingBox().maxY);
        buf.writeDouble(getBoundingBox().maxZ);
    }

    private String getMappingName()
    {
        final Optional<String> s = nameToClassBiMap.entrySet().stream()
          .filter(f -> this.getClass().equals(f.getValue().getA()))
          .map(Map.Entry::getKey)
          .findFirst();

        if (!s.isPresent())
        {
            throw new IllegalStateException(this.getClass() + " is missing a mapping! This is a bug!");
        }

        return s.get();
    }

    /**
     * Executed when a work order is added.
     * <p>
     * Override this when something need to be done when the work order is added
     *
     * @param colony         in which the work order exist
     * @param readingFromNbt if being read from NBT.
     */
    @Override
    public void onAdded(final IColony colony, final boolean readingFromNbt)
    {
        /*
         * Intentionally left empty.
         */
    }

    /**
     * Executed when a work order is completed.
     * <p>
     * Override this when something need to be done when the work order is completed
     *
     * @param colony  in which the work order exist
     * @param citizen citizen that completed the work order
     */
    @Override
    public void onCompleted(final IColony colony, ICitizenData citizen)
    {
        final Blueprint blueprint = getBlueprint();
        if (blueprint != null)
        {
            final CompoundTag[][][] tileEntityData = blueprint.getTileEntities();
            for (short x = 0; x < blueprint.getSizeX(); x++)
            {
                for (short y = 0; y < blueprint.getSizeY(); y++)
                {
                    for (short z = 0; z < blueprint.getSizeZ(); z++)
                    {
                        final CompoundTag compoundNBT = tileEntityData[y][z][x];
                        if (compoundNBT != null && compoundNBT.contains(TAG_BLUEPRINTDATA))
                        {
                            final BlockPos offset = new BlockPos(x, y, z);
                            final BlockPos tePos = getLocation().subtract(blueprint.getPrimaryBlockOffset()).offset(offset);
                            final BlockEntity te = colony.getWorld().getBlockEntity(tePos);
                            if (te instanceof IBlueprintDataProviderBE blueprintDataProviderBE)
                            {
                                final CompoundTag tagData = compoundNBT.getCompound(TAG_BLUEPRINTDATA);
                                tagData.putString(NbtTagConstants.TAG_PACK, blueprint.getPackName());
                                if (blueprint.getPrimaryBlockOffset().equals(offset))
                                {
                                    tagData.putString(NbtTagConstants.TAG_PATH, StructurePacks.getStructurePack(blueprint.getPackName()).getSubPath(Utils.resolvePath(blueprint.getFilePath(), tagData.getString(TAG_SCHEMATIC_NAME))) + ".blueprint");
                                }

                                try
                                {
                                    blueprintDataProviderBE.readSchematicDataFromNBT(compoundNBT);
                                }
                                catch (final Exception e)
                                {
                                    Log.getLogger().warn("Broken deco-controller at: {}", offset);
                                }
                                ((ServerLevel) colony.getWorld()).getChunkSource().blockChanged(tePos);
                                te.setChanged();
                            }
                        }
                    }
                }
            }
        }
        colony.getWorkManager().removeWorkOrder(this.getID());
    }

    /**
     * Executed when a work order is removed.
     * <p>
     * Override this when something need to be done when the work order is removed
     *
     * @param colony in which the work order exist
     */
    @Override
    public void onRemoved(final IColony colony)
    {
        /*
         * Intentionally left empty.
         */
    }

    /**
     * Check if this workOrder can be resolved by an existing builder.
     *
     * @param colony the colony to check in.
     * @param level  the new level of the building.
     * @return true if so.
     */
    @Override
    public boolean canBeResolved(final IColony colony, final int level)
    {
        return colony.getServerBuildingManager()
          .getBuildings()
          .values()
          .stream()
          .anyMatch(building -> building instanceof BuildingBuilder && !building.getAllAssignedCitizen().isEmpty() && building.getBuildingLevel() >= level);
    }

    /**
     * Check if this workOrder can be resolved by an existing builder by distance.
     *
     * @param colony the colony to check in.
     * @param level  the new level of the building.
     * @return true if so.
     */
    @Override
    public boolean tooFarFromAnyBuilder(final IColony colony, final int level)
    {
        return false;
    }

    @Override
    public BuildingProgressStage getStage()
    {
        return stage;
    }

    @Override
    public void setStage(final BuildingProgressStage stage)
    {
        if (stage != this.stage)
        {
            changed = true;
            this.stage = stage;
        }
    }
}

package com.minecolonies.core.colony.workorders;

import com.ldtteam.structurize.blueprints.v1.Blueprint;
import com.ldtteam.structurize.storage.StructurePacks;
import com.minecolonies.api.advancements.AdvancementTriggers;
import com.minecolonies.api.colony.ICitizenData;
import com.minecolonies.api.colony.IColony;
import com.minecolonies.api.colony.buildings.IBuilding;
import com.minecolonies.api.colony.workorders.IBuilderWorkOrder;
import com.minecolonies.api.colony.workorders.IServerWorkOrder;
import com.minecolonies.api.colony.workorders.IWorkManager;
import com.minecolonies.api.colony.workorders.IWorkOrder;
import com.minecolonies.api.util.ColonyUtils;
import com.minecolonies.api.util.Log;
import com.minecolonies.api.util.MessageUtils;
import com.minecolonies.core.colony.Colony;
import com.minecolonies.core.colony.buildings.AbstractBuildingStructureBuilder;
import com.minecolonies.core.colony.buildings.modules.WorkerBuildingModule;
import com.minecolonies.core.colony.buildings.modules.settings.StringSetting;
import com.minecolonies.core.util.AdvancementUtils;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.ListTag;
import net.minecraft.nbt.Tag;
import net.minecraft.util.Tuple;
import net.minecraft.world.level.ChunkPos;
import net.minecraft.world.level.Level;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

import java.util.*;
import java.util.function.Predicate;
import java.util.stream.Collectors;

import static com.minecolonies.api.util.constant.TranslationConstants.OUT_OF_COLONY;
import static com.minecolonies.core.colony.buildings.workerbuildings.BuildingBuilder.MANUAL_SETTING;
import static com.minecolonies.core.colony.buildings.workerbuildings.BuildingBuilder.MODE;

/**
 * Handles work orders for a colony.
 */
public class WorkManager implements IWorkManager
{
    /**
     * Workorder NBT tags.
     */
    private static final String TAG_WORK_ORDERS = "workOrders";
    private static final String TAG_NEW_SYSTEM  = "newsystem";

    //  Once a second
    //private static final int    WORK_ORDER_FULFILL_INCREMENT = 1 * 20;
    /**
     * The Colony the workManager takes part of.
     */
    private final Colony                         colony;
    @NotNull
    private final Map<Integer, IServerWorkOrder> workOrders     = new LinkedHashMap<>();
    private       int                            topWorkOrderId = 0;
    /**
     * Checks if there has been changes.
     */
    private              boolean                  dirty           = false;

    /**
     * Constructor, saves reference to the colony.
     *
     * @param c Colony the work manager is for.
     */
    public WorkManager(final Colony c)
    {
        colony = c;
    }

    /**
     * Removes a work order from the work manager.
     *
     * @param order {@link IWorkOrder} to remove.
     */
    @Override
    public void removeWorkOrder(@Nullable final IServerWorkOrder order)
    {
        if (order == null)
        {
            return;
        }
        removeWorkOrder(order.getID());
    }

    /**
     * Removes a work order from the work manager.
     *
     * @param orderId ID of the order to remove
     */
    @Override
    public void removeWorkOrder(final int orderId)
    {
        final IWorkOrder workOrder = workOrders.get(orderId);
        if (workOrder != null)
        {
            if (workOrder.isClaimed())
            {
                final IBuilding building = colony.getServerBuildingManager().getBuilding(workOrder.getClaimedBy());
                if (building instanceof AbstractBuildingStructureBuilder abstractBuildingStructureBuilder)
                {
                    abstractBuildingStructureBuilder.onWorkOrderCancellation(workOrder);
                }
            }

            dirty = true;
            workOrders.remove(orderId);
            colony.removeWorkOrderInView(orderId);
            if (workOrder instanceof IBuilderWorkOrder builderWorkOrder)
            {
                builderWorkOrder.onRemoved(colony);
            }
            colony.markDirty();
        }
    }

    /**
     * Get a work order of the specified id, as a specific type.
     *
     * @param id   the id of the work order.
     * @param type the class of the expected type of the work order.
     * @param <W>  the type of work order to return.
     * @return the work order of the specified id, or null if it was not found or is of an incompatible type.
     */
    @Override
    @Nullable
    public <W extends IServerWorkOrder> W getWorkOrder(final int id, @NotNull final Class<W> type)
    {
        final IWorkOrder workOrder = getWorkOrder(id);
        if (type.isInstance(workOrder))
        {
            return type.cast(workOrder);
        }

        return null;
    }

    /**
     * Get a work order of the specified id.
     *
     * @param id the id of the work order.
     * @return the work order of the specified id, or null.
     */
    @Override
    public IServerWorkOrder getWorkOrder(final int id)
    {
        return workOrders.get(id);
    }

    /**
     * Get an unclaimed work order of a specified type.
     *
     * @param type the class of the type of work order to find.
     * @param <W>  the type of work order to return.
     * @return an unclaimed work order of the given type, or null if no unclaimed work order of the type was found.
     */
    @Override
    @Nullable
    public <W extends IServerWorkOrder> W getUnassignedWorkOrder(@NotNull final Class<W> type)
    {
        for (@NotNull final IWorkOrder o : workOrders.values())
        {
            if (!o.isClaimed() && type.isInstance(o))
            {
                return type.cast(o);
            }
        }

        return null;
    }

    /**
     * Get all work orders of a specified type.
     *
     * @param type the class of the type of work order to find.
     * @param <W>  the type of work order to return.
     * @return a list of all work orders of the given type.
     */
    @Override
    public <W extends IServerWorkOrder> List<W> getWorkOrdersOfType(@NotNull final Class<W> type)
    {
        return workOrders.values().stream().filter(type::isInstance).map(type::cast).collect(Collectors.toList());
    }

    /**
     * Get all work orders.
     *
     * @return a list of all work orders.
     */
    @Override
    public @NotNull Map<Integer, IServerWorkOrder> getWorkOrders()
    {
        return workOrders;
    }

    /**
     * When a citizen is removed, unclaim any Work Orders that were claimed by that citizen.
     *
     * @param citizen Citizen to unclaim work for.
     */
    @Override
    public void clearWorkForCitizen(@NotNull final ICitizenData citizen)
    {
        dirty = true;
        if (citizen.getWorkBuilding() != null)
        {
            for (final IWorkOrder workOrder : workOrders.values())
            {
                if (citizen.getWorkBuilding().getPosition().equals(workOrder.getClaimedBy()))
                {
                    workOrder.setClaimedBy(null);
                }
            }
        }
    }

    /**
     * Save the Work Manager.
     *
     * @param compound Compound to save to.
     */
    @Override
    public void write(@NotNull final CompoundTag compound)
    {
        //  Work Orders
        @NotNull final ListTag list = new ListTag();
        for (@NotNull final IServerWorkOrder o : workOrders.values())
        {
            @NotNull final CompoundTag orderCompound = new CompoundTag();
            o.write(orderCompound);
            list.add(orderCompound);
        }
        compound.put(TAG_WORK_ORDERS, list);
        compound.putBoolean(TAG_NEW_SYSTEM, true);
    }

    /**
     * Restore the Work Manager.
     *
     * @param compound Compound to read from.
     */
    @Override
    public void read(@NotNull final CompoundTag compound)
    {
        workOrders.clear();

        if (!compound.contains(TAG_NEW_SYSTEM))
        {
            // On the new system, we drop all current workorders to avoid any issues.
            return;
        }

        //  Work Orders
        final ListTag list = compound.getList(TAG_WORK_ORDERS, Tag.TAG_COMPOUND);
        for (int i = 0; i < list.size(); ++i)
        {
            final CompoundTag orderCompound = list.getCompound(i);
            @Nullable final IServerWorkOrder o = AbstractWorkOrder.createFromNBT(orderCompound, this);
            if (o != null)
            {
                addWorkOrder(o, true);

                //  If this Work Order is claimed, and the Citizen who claimed it no longer exists
                //  then clear the Claimed status
                //  This is just a failsafe cleanup; this should not happen under normal circumstances
                if (o.isClaimed() && colony.getServerBuildingManager().getBuilding(o.getClaimedBy()) == null)
                {
                    o.setClaimedBy(null);
                }

                topWorkOrderId = Math.max(topWorkOrderId, o.getID());
            }
        }
    }

    /**
     * Adds work order to the work manager.
     *
     * @param order          Order adding.
     * @param readingFromNbt if being read from NBT.
     */
    @Override
    public void addWorkOrder(@NotNull final IServerWorkOrder order, final boolean readingFromNbt)
    {
        dirty = true;

        if (!(order instanceof WorkOrderMiner))
        {
            for (final IServerWorkOrder or : workOrders.values())
            {
                if (or.getLocation().equals(order.getLocation()) && or.getStructurePath().equals(order.getStructurePath()) && or.getStructurePack().equals(order.getStructurePack()))
                {
                    Log.getLogger().warn("Avoiding adding duplicate workOrder");
                    removeWorkOrder(or);
                    break;
                }
            }
            if (!readingFromNbt && !isWorkOrderWithinColony(order))
            {
                MessageUtils.format(OUT_OF_COLONY, order.getDisplayName(), order.getLocation().getX(), order.getLocation().getZ()).sendTo(colony).forAllPlayers();
                return;
            }
        }

        if (order.getID() == 0)
        {
            topWorkOrderId++;
            order.setID(topWorkOrderId);
        }

        final int level = order.getTargetLevel();
        if (!readingFromNbt)
        {
            if (order instanceof WorkOrderBuilding buildingOrder)
            {
                final IBuilding building = colony.getServerBuildingManager().getBuilding(buildingOrder.getLocation());
                if (building != null)
                {
                    AdvancementUtils.TriggerAdvancementPlayersForColony(colony,
                            player -> AdvancementTriggers.CREATE_BUILD_REQUEST.trigger(player, building.getBuildingType().getRegistryName().getPath(), level));
                }
            }
            else if (order instanceof WorkOrderDecoration)
            {
                AdvancementUtils.TriggerAdvancementPlayersForColony(colony,
                  player -> AdvancementTriggers.CREATE_BUILD_REQUEST.trigger(player, order.getFileName().replace(String.valueOf(level), ""), level));
            }
        }

        workOrders.put(order.getID(), order);
        order.onAdded(colony, readingFromNbt);
    }

    /**
     * Check if the workOrder is within a colony.
     *
     * @param order the workorder to check.
     * @return true if so.
     */
    private boolean isWorkOrderWithinColony(final IWorkOrder order)
    {
        final Level world = colony.getWorld();
        final Blueprint blueprint = StructurePacks.getBlueprint(order.getStructurePack(), order.getStructurePath());
        final Tuple<BlockPos, BlockPos> corners
          = ColonyUtils.calculateCorners(order.getLocation(),
          world,
          blueprint,
          order.getRotation(),
          order.isMirrored());

        Set<ChunkPos> chunks = new HashSet<>();
        final int minX = Math.min(corners.getA().getX(), corners.getB().getX()) + 1;
        final int maxX = Math.max(corners.getA().getX(), corners.getB().getX());

        final int minZ = Math.min(corners.getA().getZ(), corners.getB().getZ()) + 1;
        final int maxZ = Math.max(corners.getA().getZ(), corners.getB().getZ());

        for (int x = minX; x < maxX; x += 16)
        {
            for (int z = minZ; z < maxZ; z += 16)
            {
                final int chunkX = x >> 4;
                final int chunkZ = z >> 4;
                final ChunkPos pos = new ChunkPos(chunkX, chunkZ);
                if (!chunks.contains(pos))
                {
                    chunks.add(pos);
                    if (ColonyUtils.getOwningColony(world.getChunk(pos.x, pos.z)) != colony.getID())
                    {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /**
     * Process updates on the Colony Tick. Currently, does periodic Work Order cleanup.
     *
     * @param colony the colony being ticked.
     */
    @Override
    public void onColonyTick(@NotNull final IColony colony)
    {
        final List<IServerWorkOrder> orderedWorkOrders = new ArrayList<>(workOrders.size());
        final Iterator<IServerWorkOrder> iter = workOrders.values().iterator();

        // Clean up invalid orders and handle builder deconstruction scenarios
        while (iter.hasNext())
        {
            final IServerWorkOrder order = iter.next();

            if (!order.isValid(colony))
            {
                iter.remove();
                dirty = true;
                continue;
            }

            if (order.isDirty())
            {
                dirty = true;
                order.resetChange();
            }

            if (order.isClaimed()
                && colony.getServerBuildingManager().getBuilding(order.getClaimedBy()) == null)
            {
                order.setClaimedBy(BlockPos.ZERO);
            }

            orderedWorkOrders.add(order);
        }

        // Sort first by group, then by priority.
        orderedWorkOrders.sort(
            Comparator.comparing(IServerWorkOrder::isClaimed)
                .reversed()
                .thenComparing(IWorkOrder.WORK_ORDER_COMPARATOR));

        // Attempt to assign the orders.
        for (final IServerWorkOrder order : orderedWorkOrders)
        {
            tryAssignWorkOrder(order, order::canBuild);
        }
    }

    /**
     * Try assign a workorder to a structure builder (miner, builder, etc).
     * @param order the workorder to assign.
     * @param predicate checks to execute before assignment.
     */
    private void tryAssignWorkOrder(final IServerWorkOrder order, @NotNull Predicate<IBuilding> predicate)
    {
        for (IBuilding building : colony.getServerBuildingManager().getBuildings().values())
        {
            if (building instanceof AbstractBuildingStructureBuilder abstractBuildingStructureBuilder)
            {
                final @Nullable ICitizenData citizen = building.getModule(WorkerBuildingModule.class).getFirstCitizen();
                if (citizen == null)
                {
                    continue;
                }

                if (abstractBuildingStructureBuilder.hasWorkOrder())
                {
                    continue;
                }

                if (order.isClaimed())
                {
                    if (order.getClaimedBy().equals(building.getPosition()))
                    {
                        abstractBuildingStructureBuilder.setWorkOrder(order);
                        order.setClaimedBy(building.getID());
                        return;
                    }
                    continue;
                }

                final StringSetting setting = building.getSetting(MODE);
                if (setting != null && setting.getValue().equals(MANUAL_SETTING))
                {
                    continue;
                }

                if (predicate.test(building))
                {
                    abstractBuildingStructureBuilder.setWorkOrder(order);
                    order.setClaimedBy(building.getID());
                    return;
                }
            }
        }
    }

    /**
     * Get an ordered list by priority of the work orders.
     *
     * @param builder the builder wanting to claim it.
     * @param type    the type of workOrder which is required.
     * @param <W>     the type.
     * @return the list.
     */
    @Override
    public <W extends IServerWorkOrder> List<W> getOrderedList(Class<W> type, BlockPos builder)
    {
        return getOrderedList(type::isInstance, builder)
          .stream()
          .map(m -> (W) m)
          .collect(Collectors.toList());
    }

    /**
     * Get an ordered list by priority of the work orders.
     *
     * @param builder   the builder wanting to claim it.
     * @param predicate a predicate to check each item against
     * @return the list.
     */
    @Override
    public List<IServerWorkOrder> getOrderedList(@NotNull Predicate<IServerWorkOrder> predicate, final BlockPos builder)
    {
        return workOrders.values().stream()
          .filter(o -> (!o.isClaimed() || o.getClaimedBy().equals(builder)))
          .filter(predicate)
          .sorted(IWorkOrder.WORK_ORDER_COMPARATOR)
          .collect(Collectors.toList());
    }

    /**
     * Checks if changes has been made.
     *
     * @return true if so.
     */
    @Override
    public boolean isDirty()
    {
        return dirty;
    }

    /**
     * Sets if changes has been made.
     *
     * @param dirty true if so. False to reset.
     */
    @Override
    public void setDirty(final boolean dirty)
    {
        this.dirty = dirty;
    }

    @Override
    public IColony getColony()
    {
        return colony;
    }
}

package com.minecolonies.core.colony.workorders;

import com.minecolonies.api.advancements.AdvancementTriggers;
import com.minecolonies.api.colony.ICitizenData;
import com.minecolonies.api.colony.IColony;
import com.minecolonies.api.colony.buildings.IBuilding;
import com.minecolonies.api.colony.workorders.IWorkManager;
import com.minecolonies.api.colony.workorders.WorkOrderType;
import com.minecolonies.core.colony.buildings.workerbuildings.BuildingBuilder;
import com.minecolonies.core.entity.ai.workers.util.ConstructionTapeHelper;
import com.minecolonies.core.util.AdvancementUtils;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.network.chat.Component;
import org.jetbrains.annotations.NotNull;

/**
 * Represents one building order to complete. Has his own structure for the building.
 */
public class WorkOrderBuilding extends AbstractWorkOrder
{
    private static final String TAG_CUSTOM_NAME            = "customName";
    private static final String TAG_CUSTOM_PARENT_NAME     = "customParentName";
    private static final String TAG_PARENT_TRANSLATION_KEY = "parentTranslationKey";

    /**
     * Maximum distance a builder can have from the building site.
     */
    private static final double MAX_DISTANCE_SQ = 100 * 100;

    /**
     * The custom name of the building.
     */
    private String customName;

    /**
     * The custom name of the parent building.
     */
    private String customParentName;

    /**
     * The translation key of the parent building.
     */
    private String parentTranslationKey;

    public static WorkOrderBuilding create(@NotNull final WorkOrderType type, @NotNull final IBuilding building)
    {
        int targetLevel = building.getBuildingLevel();
        switch (type)
        {
            case BUILD:
                targetLevel = 1;
                break;
            case UPGRADE:
                targetLevel++;
                break;
            case REMOVE:
                targetLevel = 0;
                break;
        }

        final int targetSchematicLevel = type == WorkOrderType.REMOVE ? building.getBuildingLevel() : targetLevel;
        String schemPath = building.getBlueprintPath().replace(".blueprint", "");
        schemPath = schemPath.substring(0, schemPath.length() - 1) + targetSchematicLevel + ".blueprint";
        WorkOrderBuilding wo = new WorkOrderBuilding(
          building.getStructurePack(),
          schemPath,
          building.getBuildingType().getTranslationKey(),
          type,
          building.getID(),
          building.getRotation(),
          building.getTileEntity() == null ? building.isMirrored() : building.getTileEntity().isMirrored(),
          building.getBuildingLevel(),
          targetLevel);
        wo.setCustomName(building);
        wo.setColony(building.getColony());
        return wo;
    }

    /**
     * Unused constructor for reflection.
     */
    public WorkOrderBuilding()
    {
        super();
    }

    private WorkOrderBuilding(
      String packName,
      String path,
      String translationKey,
      WorkOrderType workOrderType,
      BlockPos location,
      int rotation,
      boolean isMirrored,
      int currentLevel,
      int targetLevel)
    {
        super(packName, path, translationKey, workOrderType, location, rotation, isMirrored, currentLevel, targetLevel);
    }

    public String getCustomName()
    {
        return customName;
    }

    public String getCustomParentName()
    {
        return customParentName;
    }

    public String getParentTranslationKey()
    {
        return parentTranslationKey;
    }

    public void setCustomName(@NotNull final IBuilding building)
    {
        this.customName = building.getCustomName();
        this.customParentName = "";
        this.parentTranslationKey = "";

        if (building.hasParent())
        {
            final IBuilding parentBuilding = building.getColony().getServerBuildingManager().getBuilding(building.getParent());
            if (parentBuilding != null)
            {
                this.customParentName = parentBuilding.getCustomName();
                this.parentTranslationKey = parentBuilding.getBuildingType().getTranslationKey();
            }
        }
    }

    @Override
    public Component getDisplayName()
    {
        String customParentName = getCustomParentName();
        String customName = getCustomName();
        Component buildingComponent = customName.isEmpty() ? Component.translatable(getTranslationKey()) : Component.literal(customName);

        if (parentTranslationKey.isEmpty())
        {
            return buildingComponent;
        }
        else
        {
            Component parentComponent = customParentName.isEmpty() ? Component.translatable(parentTranslationKey) : Component.literal(customParentName);
            return Component.translatable("%s / %s", parentComponent, buildingComponent);
        }
    }

    @Override
    public boolean canBuild(final IBuilding building)
    {
        //  A Build WorkOrder may be fulfilled by a Builder as long as any ONE of the following is true:
        //  - The Builder's Work AbstractBuilding is built
        //  - OR the WorkOrder is for the Builder's Work AbstractBuilding
        //  - OR the WorkOrder is for the TownHall
        //  - OR the WorkOrder is not farther away than 100 blocks from any builder and not manually assigned

        return building instanceof BuildingBuilder
            && canBuildIgnoringDistance(building, building.getPosition(), building.getBuildingLevel())
            && (building.getPosition().distSqr(getLocation()) <= MAX_DISTANCE_SQ);
    }

    /**
     * Checks if a builder may accept this workOrder while ignoring the distance to the builder.
     *
     * @param builderLocation position of the builders own hut.
     * @param builderLevel    level of the builders hut.
     * @return true if so.
     */
    @Override
    public boolean canBuildIgnoringDistance(@NotNull IBuilding building, @NotNull final BlockPos builderLocation, final int builderLevel)
    {
        //  A Build WorkOrder may be fulfilled by a Builder as long as any ONE of the following is true:
        //  - The Builder's Work AbstractBuilding is built
        //  - OR the WorkOrder is for the Builder's Work AbstractBuilding

        return (builderLevel >= this.getTargetLevel() || builderLevel == BuildingBuilder.MAX_BUILDING_LEVEL || (builderLocation.equals(getLocation())));
    }

    @Override
    public boolean tooFarFromAnyBuilder(final IColony colony, final int level)
    {
        return colony.getServerBuildingManager()
          .getBuildings()
          .values()
          .stream()
          .noneMatch(building -> building instanceof BuildingBuilder && !building.getAllAssignedCitizen().isEmpty()
                                   && building.getPosition().distSqr(getLocation()) <= MAX_DISTANCE_SQ);
    }

    /**
     * Is this WorkOrder still valid?  If not, it will be deleted.
     *
     * @param colony The colony that owns the Work Order.
     * @return True if the building for this work order still exists.
     */
    @Override
    public boolean isValid(@NotNull final IColony colony)
    {
        return super.isValid(colony) && colony.getServerBuildingManager().getBuilding(getLocation()) != null;
    }

    /**
     * Read the WorkOrder data from the CompoundTag.
     *
     * @param compound NBT Tag compound.
     * @param manager  the work manager.
     */
    @Override
    public void read(@NotNull final CompoundTag compound, final IWorkManager manager)
    {
        super.read(compound, manager);
        customName = compound.getString(TAG_CUSTOM_NAME);
        customParentName = compound.getString(TAG_CUSTOM_PARENT_NAME);
        parentTranslationKey = compound.getString(TAG_PARENT_TRANSLATION_KEY);
    }

    /**
     * Save the Work Order to an CompoundTag.
     *
     * @param compound NBT tag compound.
     */
    @Override
    public void write(@NotNull final CompoundTag compound)
    {
        super.write(compound);
        compound.putString(TAG_CUSTOM_NAME, customName);
        compound.putString(TAG_CUSTOM_PARENT_NAME, customParentName);
        compound.putString(TAG_PARENT_TRANSLATION_KEY, parentTranslationKey);
    }

    @Override
    public void serializeViewNetworkData(@NotNull FriendlyByteBuf buf)
    {
        super.serializeViewNetworkData(buf);
        buf.writeUtf(customName);
        buf.writeUtf(customParentName);
        buf.writeUtf(parentTranslationKey);
    }

    @Override
    public void onCompleted(final IColony colony, ICitizenData citizen)
    {
        super.onCompleted(colony, citizen);

        if (getWorkOrderType() != WorkOrderType.REMOVE)
        {
            final IBuilding building = colony.getServerBuildingManager().getBuilding(getLocation());
            if (building != null)
            {
                AdvancementUtils.TriggerAdvancementPlayersForColony(colony,
                        player -> AdvancementTriggers.COMPLETE_BUILD_REQUEST.trigger(player, building.getBuildingType().getRegistryName().getPath(), this.getTargetLevel()));
            }
        }
    }

    @Override
    public void onAdded(final IColony colony, final boolean readingFromNbt)
    {
        if (!readingFromNbt && colony != null && colony.getWorld() != null)
        {
            final IBuilding building = colony.getServerBuildingManager().getBuilding(getLocation());
            if (building != null)
            {
                ConstructionTapeHelper.placeConstructionTape(building.getCorners(), colony);
            }
        }
    }

    @Override
    public void onRemoved(final IColony colony)
    {
        final IBuilding building = colony.getServerBuildingManager().getBuilding(getLocation());
        if (building != null)
        {
            building.markDirty();
            ConstructionTapeHelper.removeConstructionTape(building.getCorners(), colony.getWorld());
        }
    }
}
